<script setup lang="ts">import{onMounted,reactive,ref}from"vue";import{ElMessage,type UploadFile}from"element-plus";import{createSeal,listDepartments,listSeals,updateSeal,uploadSeal,type Option,type Seal}from"@/api/business";const rows=ref<Seal[]>([]),departments=ref<Option[]>([]),dialog=ref(false);const form=reactive({name:"",department:undefined as number|undefined,active:true});async function load(){[rows.value,departments.value]=await Promise.all([listSeals(),listDepartments()])}async function create(){await createSeal(form);dialog.value=false;ElMessage.success("公章已创建");await load()}async function toggle(row:Seal){await updateSeal(row.id,{active:!row.active});await load()}async function upload(row:Seal,file:UploadFile){if(!file.raw)return;await uploadSeal(row.id,file.raw);ElMessage.success("新版本已上传");await load()}onMounted(load);</script>
<template><div class="page"><header><div><h2>公章管理</h2><p>各部门独立维护多枚公章、版本和启停状态</p></div><el-button type="primary" @click="dialog=true">新增公章</el-button></header><el-table :data="rows" border><el-table-column prop="name" label="公章名称"/><el-table-column prop="department_name" label="部门"/><el-table-column label="版本" width="90"><template #default="s">{{s.row.versions.length}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.active?'success':'info'">{{s.row.active?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="220"><template #default="s"><el-upload :auto-upload="false" :show-file-list="false" accept="image/*" :on-change="f=>upload(s.row,f)"><el-button link type="primary">上传新版本</el-button></el-upload><el-button link @click="toggle(s.row)">{{s.row.active?'停用':'启用'}}</el-button></template></el-table-column></el-table><el-dialog v-model="dialog" title="新增公章" width="480"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="所属部门"><el-select v-model="form.department" class="full"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :disabled="!form.name||!form.department" @click="create">创建</el-button></template></el-dialog></div></template><style scoped>.page{padding:20px}header{display:flex;justify-content:space-between;margin-bottom:18px}h2{margin:0;font-size:20px;letter-spacing:0}p{color:#73767a}.full{width:100%}:deep(.el-upload){display:inline-block}</style>
